    static_assert(LEN_ARRAY(dmall_animation_table) == DMALL_ANIM_COUNT);

    config_animation_entry_t get_config_animation_name_dmall(size_t index) {
        assert(index < DMALL_ANIM_COUNT);
        const auto& entry = dmall_animation_table[index];
        return { DMALL_STRINGS + entry.name, DMALL_STRINGS + entry.id, DMALL_STRINGS + entry.fqid, DMALL_STRINGS + entry.fqname, entry.anim_index, entry.set, entry.layout };
    }

    int config_parse_animation_name_dmall(config::config_t& config, const char *value) {
        int ret = -1;
        for (size_t i = 0;ret < 0 && i < DMALL_ANIM_COUNT;++i) {
            const auto& entry = dmall_animation_table[i];
            if (strcmp(value, DMALL_STRINGS + entry.name) == 0 ||
                strcmp(value, DMALL_STRINGS + entry.id) == 0 ||
                strcmp(value, DMALL_STRINGS + entry.fqid) == 0 ||
                strcmp(value, DMALL_STRINGS + entry.fqname) == 0 ||
                strcmp(value, ALT_DMALL_STRINGS + entry.alt_fqid) == 0 ||
                strcmp(value, ALT_DMALL_STRINGS + entry.alt_fqname) == 0) {
                config.animation_index = entry.anim_index;
                config.animation_dm_set = entry.set;
                config.animation_sprite_sheet_layout = entry.layout;
                ret = entry.anim_index;
                break;
            }
        }
        return ret;
    }
